{"content": "def payload(owner):
    return {"owner": owner}

def enqueue(payload, mode="all"):
    """Enqueue a payload with optional mode. Mode defaults to 'all' for legacy compatibility."""
    # Store the payload and mode together
    return {"_payload": payload, "_mode": mode}
